/* Real Chrome acceptance for isolated Boss / essence flows.
 * RPG_BOSS_QA=1, loopback 9763/9762, in-memory SQLite only.
 * --cases=layout,exchange,exchange-race,attack,kill,cap,races --run-id=...
 * Exact continuations: --cases=attack-tail --resume-run=<failed-attack>;
 * read-only bridge: --cases=cap-view --bridge-run=<cap-with-assets-gap>.
 * Never use --resume-run to repeat a whole mutation segment.
 * Segments keep failure evidence. Completed writes are never automatically replayed.
 */
'use strict';
