const selected=(args.get('cases')||'layout,exchange,exchange-race,attack,kill,cap,races').split(',');
assert(selected.length&&new Set(selected).size===selected.length&&selected.every(x=>['layout','exchange','exchange-race','attack','kill','cap','races','pure','focus','attack-tail','cap-view'].includes(x)),'Unknown case');
if(args.has('resume-run'))assert(selected.length===1&&selected[0]==='attack-tail'&&!args.has('bridge-run'),'--resume-run only supports the exact attack-tail continuation; whole mutation segments cannot resume');
if(args.has('bridge-run'))assert(selected.length===1&&selected[0]==='cap-view'&&!args.has('resume-run'),'--bridge-run only supports the read-only cap-view bridge');
function local(value){const u=new URL(value);assert(u.protocol==='http:'&&u.hostname==='127.0.0.1'&&!u.username&&!u.password&&u.pathname==='/'&&!u.search&&!u.hash&&Number(u.port)>=1024,'Loopback only');return u.origin;}
const origin=local(process.env.BOSS_SCENE_ORIGIN||'http://127.0.0.1:9763'),api=local(process.env.BOSS_API_ORIGIN||'http://127.0.0.1:9762');assert.notEqual(origin,api);
const runId=args.get('run-id')||new Date().toISOString().replace(/[:.]/g,'-')+'-'+process.pid,base=path.join(repo,'.release-sync/boss-20261105'),dir=path.join(base,'browser',runId);
assert(!fs.existsSync(path.join(dir,'results.json')),'Never overwrite an earlier browser run');fs.mkdirSync(dir,{recursive:true});
const q=x=>JSON.stringify(String(x)),sb=a=>'[data-sb-action='+q(a)+']',sha=b=>crypto.createHash('sha256').update(b).digest('hex');
